CREATE TABLE `video_queue`( `video_queue_id` INT UNSIGNED NOT NULL AUTO_INCREMENT, `file_id` INT UNSIGNED NOT NULL, `type` ENUM('sbfs','storage') NOT NULL, `status` ENUM('pending','processing','completed','failed') NOT NULL, `createdOn` DATETIME NOT NULL, `modifiedOn` DATETIME NOT NULL, PRIMARY KEY (`id`) ) CHARSET=utf8 COLLATE=utf8_general_ci;